unsafe fn getHash(
    mut data: *const c_uchar,
    mut size: size_t,
    mut pos: size_t,
) -> c_uint {
    if pos >= size {
        return 0 as c_uint;
    }

    let remaining = size.wrapping_sub(pos);
    let result = if remaining >= 3 as size_t {
        let p = data.wrapping_add(pos);
        // SAFETY: remaining >= 3 and pos < size guarantee p, p.add(1), and p.add(2) are within the original allocation.
        ((*p as c_uint) << 0 as c_uint)
            ^ ((*p.add(1) as c_uint) << 4 as c_uint)
            ^ ((*p.add(2) as c_uint) << 8 as c_uint)
    } else {
        let p = data.wrapping_add(pos);
        if remaining == 1 as size_t {
            // SAFETY: remaining == 1 and pos < size guarantee p is within the original allocation.
            (*p as c_uint) << 0
        } else {
            // SAFETY: remaining == 2 and pos < size guarantee p and p.add(1) are within the original allocation.
            ((*p as c_uint) << 0) ^ ((*p.add(1) as c_uint) << 8)
        }
    };

    result & HASH_BIT_MASK
}

